[{"order":1,"type":"heading","text":"Performance and Load Testing Integration (JMeter, k6)"},{"order":2,"type":"paragraph","text":"Integrating performance and load testing into your automation pipeline ensures that your applications maintain high availability and speed under heavy user traffic. In this tutorial, we explore how to configure and run JMeter and k6 tests programmatically."},{"order":3,"type":"subheading","text":"1. JMeter Integration via Maven"},{"order":4,"type":"paragraph","text":"Apache JMeter can be easily integrated into a CI/CD pipeline using the JMeter Maven plugin. This allows you to execute .jmx test plans directly from your build server."},{"order":5,"type":"code","text":"<plugin>
    <groupId>com.lazerycode.jmeter</groupId>
    <artifactId>jmeter-maven-plugin</artifactId>
    <version>3.6.0</version>
    <executions>
        <execution>
            <id>configuration</id>
            <goals>
                <goal>configure</goal>
                <goal>generate-gui-reports</goal>
            </goals>
        </execution>
        <execution>
            <id>jmeter-tests</id>
            <goals>
                <goal>jmeter</goal>
            </goals>
        </execution>
    </executions>
</plugin>"},{"order":6,"type":"subheading","text":"2. Modern Load Testing with k6"},{"order":7,"type":"paragraph","text":"k6, developed by Grafana, uses JavaScript for writing test scripts, making it developer-friendly and natively optimized for automation. Below is a standard load testing script configured for k6."},{"order":8,"type":"code","text":"import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  stages: [
    { duration: '30s', target: 20 },
    { duration: '1m', target: 50 },
    { duration: '10s', target: 0 },
  ],
};

export default function () {
  const res = http.get('https://test-api.k6.io/public/crocodiles/');
  check(res, { 'status was 200': (r) => r.status === 200 });
  sleep(1);
}"},{"order":9,"type":"subheading","text":"3. Best Practices for CI/CD Integration"},{"order":10,"type":"bullet_point","text":"Run performance tests in an isolated environment that closely mirrors production."},{"order":11,"type":"bullet_point","text":"Set strict performance thresholds and fail builds when latency or error rates exceed acceptable limits."},{"order":12,"type":"bullet_point","text":"Store test results as build artifacts for trend analysis over time."}]
